:root{font-family:"DM Sans",sans-serif;color:#20312d;background:#f4f6f2;font-synthesis:none;--ink:#20312d;--muted:#75817b;--green:#176b58;--green-dark:#105244;--mint:#e3f2eb;--line:#e4e9e4;--red:#bd423a;--amber:#a76513;--paper:#fff;--soft:#f7f9f6;--heading:"Manrope",sans-serif}*{box-sizing:border-box}body{margin:0;min-width:320px}button,input,select{font:inherit}button{cursor:pointer}.hidden{display:none!important}.login-screen{min-height:100vh;display:grid;grid-template-columns:minmax(360px,48%) 1fr;background:#fff}.login-panel{width:min(390px,calc(100% - 48px));align-self:center;justify-self:center;padding:56px 0}.brand-mark{width:48px;height:48px;display:grid;place-items:center;border-radius:14px;background:#176b58;color:white;font:800 15px var(--heading);box-shadow:0 6px 16px #176b582b}.brand-mark.small{width:38px;height:38px;border-radius:11px;font-size:12px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:1.5px;color:#89958f;margin:0 0 8px}.login-panel .eyebrow{margin-top:32px}.login-panel h1{font:800 34px var(--heading);letter-spacing:0;margin:0 0 8px}.muted{color:var(--muted);font-size:14px;margin:0}.stack-form{display:grid;gap:18px;margin-top:34px}.stack-form label,.form-grid label,.management-form label{display:grid;gap:8px;font-size:12px;font-weight:700;color:#44524c}.stack-form input,.form-grid input,.form-grid select,.management-form input,.management-form select,.compact-label select,.inline-form input{width:100%;height:43px;border:1px solid #dfe5df;border-radius:6px;padding:0 12px;background:#fff;color:var(--ink);outline:none}.stack-form input:focus,.form-grid input:focus,.form-grid select:focus,.search-box:focus-within,.management-form input:focus,.management-form select:focus{border-color:#5ba28c;box-shadow:0 0 0 3px #176b5818}.button{border:0;border-radius:6px;padding:11px 15px;font-weight:700;font-size:12px;transition:background .16s,transform .16s}.button:active{transform:translateY(1px)}.button.primary{color:white;background:var(--green)}.