ote{text-align:center;color:#9aa49e;font-size:9px;margin:9px 0 0}.table-search{max-width:470px;margin-bottom:15px}.table-wrap{overflow:auto;background:white;border:1px solid var(--line);border-radius:7px}table{width:100%;border-collapse:collapse;min-width:650px;text-align:left}th{background:#f8faf8;color:#8a958f;text-transform:uppercase;font-size:9px;letter-spacing:.8px;padding:12px 14px;font-weight:700}td{padding:13px 14px;border-top:1px solid #edf0ed;color:#46534c;font-size:11px}td strong{color:#23332d}.status{display:inline-block;border-radius:20px;padding:4px 8px;font-size:9px;font-weight:700}.status.ok{background:#e9f4ed;color:#28734f}.status.low,.status.expired{background:#fbeceb;color:#b43f37}.status.soon{background:#fff3df;color:#a76513}.status.inactive{background:#edf0ed;color:#707b75}.row-actions{display:flex;gap:5px}.row-actions button{border:1px solid #e2e8e2;background:#fff;border-radius:4px;color:#53645b;font-size:10px;padding:5px 8px}.row-actions button.danger{color:#b43f37}.alert-summary{display:flex;gap:9px;margin:-3px 0 14px;flex-wrap:wrap}.alert-item{padding:8px 11px;border-radius:5px;background:#fbefed;color:#a9443d;font-size:10px}.alert-item.soon{background:#fff4e2;color:#986018}.management-form{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));align-items:end;gap:12px;max-width:1000px;background:#fff;border:1px solid var(--line);border-radius:7px;padding:18px}.management-form .button{grid-column:span 2;height:43px}.form-hint{color:#839089;font-size:11px}.report-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:18px}.metric-card{background:white;border:1px solid var(--line);border-radius:7px;padding:17px}.metric-card span{color:#85918a;font-size:10px}.metric-card strong{display:block;font:800 24px var(--heading);margin-top:9px;color:#176b58}.report-columns{display:grid;grid-template-columns:1fr 1fr;gap:14px}.report-block{background:#fff;border:1px solid var(--line);border-radius:7px;padding:16px